def calculate_inverse_prob(start: int, end: int) -> int:
    """Calculates the inverse of the probability 'a' that a randomly chosen 5-digit number satisfies the given condition.

    Args:
        start: The starting value of the range (inclusive).
        end: The ending value of the range (inclusive).

    Returns:
        The rounded integer value of 1/a, or None if the probability is zero.
    """

    if start > end:
      return None  

    count_valid = 0
    for num in range(start, end + 1):
        str_num = str(num)
        if validate_condition(str_num):
            count_valid += 1

    probability = count_valid / (end - start + 1)
    if probability == 0:
      return None  
    return round(1 / probability)


def validate_condition(num_str: str) -> bool:
    """Validates if a 5-digit number satisfies the given condition."""

    a1, a2, a3, a4, a5 = int(num_str[0]), int(num_str[1]), int(num_str[2]), int(num_str[3]), int(num_str[4])
    return (a1 <= a2 + 1) and (a2 + 1 <= a3 - 7) and (a3 - 7 < a4) and (a4 <= a5 + 2)
